import SourceTag from './SourceTag.jsx';

/** Renders a narrative section (summary text or a list of points). Shows a
 * clear "needs research" placeholder instead of pretending to have real
 * data when a field hasn't been manually researched yet, and a distinct
 * "auto-generated" notice for data-derived bull/bear bullet points so it's
 * never mistaken for human analyst commentary. */
export default function NarrativeCard({ title, section }) {
  if (!section) {
    return (
      <section className="summary-section" aria-labelledby={`${title}-heading`}>
        <h2 id={`${title}-heading`}>{title}</h2>
        <p className="empty-state">Not available for this company.</p>
      </section>
    );
  }

  if (section.needsResearch) {
    return (
      <section className="summary-section needs-research" aria-labelledby={`${title}-heading`}>
        <h2 id={`${title}-heading`}>{title}</h2>
        <p className="research-flag" role="status">
          ⚠ Research needed: {section.researchNote}
        </p>
      </section>
    );
  }

  return (
    <section className="summary-section" aria-labelledby={`${title}-heading`}>
      <h2 id={`${title}-heading`}>{title}</h2>

      {section.autoGenerated && (
        <p className="auto-generated-flag" role="status">
          🤖 {section.note}
        </p>
      )}

      {section.summary && <p>{section.summary}</p>}

      {Array.isArray(section.points) && (
        <ul>
          {section.points.map((point) => (
            <li key={point}>{point}</li>
          ))}
        </ul>
      )}

      {section.rating && (
        <div className="consensus-details">
          <p>
            <strong>Rating:</strong> {section.rating}
            {section.numberOfAnalysts != null && ` (${section.numberOfAnalysts} analysts)`}
          </p>
          {section.breakdown && (
            <p className="consensus-breakdown">
              Strong Buy {section.breakdown.strongBuy} · Buy {section.breakdown.buy} · Hold{' '}
              {section.breakdown.hold} · Sell {section.breakdown.sell} · Strong Sell{' '}
              {section.breakdown.strongSell}
            </p>
          )}
          {section.trendDirection && (
            <p className="consensus-trend">Analyst sentiment has {section.trendDirection} month-on-month.</p>
          )}
          <p>
            <strong>12-month price target:</strong>{' '}
            {section.priceTarget12m ? `${section.priceTarget12m} ${section.currency || ''}` : 'Not available'}
          </p>
          {section.priceTargetNote && <p className="hint">{section.priceTargetNote}</p>}
          {section.aliasNote && <p className="hint">ℹ {section.aliasNote}</p>}
        </div>
      )}

      <SourceTag source={section.source} asOf={section.asOf} />
    </section>
  );
}
